// RED DETERMINISTICA DE LA RAMA INFO (Martin, 2026-07-31)
//
// Antes esto era una linea: copiaba `respuestaInfo` y si venia vacio el turno
// escalaba. Ronda real del 31: "¿a que hora abren los sabados?" -> handoff, con
// el Agente Intencion clasificando BIEN (intencion=info) y el horario cargado en
// bot.info_negocio. El dato estaba y nadie fue a buscarlo.
//
// La causa es una contradiccion en el propio system prompt del agente: le dice
// "tu UNICA salida es una clasificacion, NO redactas la respuesta al cliente" y
// cuatro lineas despues "para info devolve la respuesta textual en
// respuestaInfo". Cuando gana la primera, el campo queda vacio. Encima
// `respuestaInfo` no esta en `required`, asi que el output parser lo deja pasar.
//
// Se podria pelear el prompt, pero un dato que ya esta en una tabla no deberia
// depender de que un LLM se acuerde de pedirlo. `Datos Info` consulta la tabla
// SIEMPRE (misma query que la tool, con $1='' que trae todo) y aca se usa como
// respaldo. Si el agente contesto, gana su redaccion; si no, se arma el texto
// desde las filas. Sin llamada LLM extra.
const d = $('Leer Intención').first().json;
const texto = String(d.respuestaInfo || '').trim();

// filas de bot.info_negocio (clave, valor). El nodo tiene alwaysOutputData, asi
// que ante error o tabla vacia llega un item sin `clave` — se filtra.
let filas = [];
try {
  filas = $('Datos Info').all()
    .map((i) => i.json)
    .filter((r) => r && r.clave && r.valor);
} catch (e) { filas = []; }

// QUE FILAS SIRVEN PARA ESTA PREGUNTA. La tabla es chica (limit 12) pero mandarla
// entera seria un mensaje ilegible. Se puntua cada fila por cuantas palabras del
// cliente aparecen en su clave o su valor, y se queda con las que matchean.
// Sin match no se inventa nada: se escala, que es la conducta vieja.
const norm = (s) => String(s || '').normalize('NFC').toLowerCase()
  .replace(/[áéíóúü]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u' }[c]))
  .replace(/ñ/g, 'n');

const PISTAS = {
  horario: ['horario', 'hora', 'abren', 'abre', 'cierran', 'cierra', 'sabado', 'sabados',
    'domingo', 'feriado', 'atienden', 'atiende', 'abierto', 'hoy', 'ahora'],
  direccion: ['direccion', 'donde', 'ubicado', 'ubicacion', 'local', 'quedan', 'queda', 'llegar'],
  pago: ['pago', 'pagar', 'tarjeta', 'efectivo', 'transferencia', 'debito', 'credito', 'mercado'],
  envio: ['envio', 'envios', 'mandan', 'mandar', 'entrega', 'domicilio', 'cadeteria'],
  plazo: ['plazo', 'demora', 'tardan', 'tarda', 'cuando', 'listo', 'urgente'],
  contacto: ['telefono', 'contacto', 'whatsapp', 'mail', 'correo', 'instagram'],
};

const pregunta = norm(d.userMessage || '');
const temas = Object.keys(PISTAS).filter((t) => PISTAS[t].some((p) => pregunta.includes(p)));

const puntuar = (r) => {
  const clave = norm(r.clave);
  let score = 0;
  for (const t of temas) {
    if (clave.includes(t)) score += 3;
    if (PISTAS[t].some((p) => clave.includes(p))) score += 2;
  }
  // palabras largas del cliente que aparezcan en la clave
  for (const w of pregunta.split(/[^a-z0-9]+/).filter((w) => w.length >= 5)) {
    if (clave.includes(w)) score += 2;
  }
  return score;
};

const relevantes = filas.map((r) => ({ ...r, _score: puntuar(r) }))
  .filter((r) => r._score > 0)
  .sort((a, b) => b._score - a._score)
  .slice(0, 4);

// El respaldo se arma con el dato CRUDO de la tabla. No es la prosa mas linda,
// pero es verdadera y llega — que es infinitamente mejor que un mail.
const respaldo = relevantes.map((r) => String(r.valor).trim()).join('\n');

const final = texto || respaldo;

return [{ json: {
  ...d,
  final,
  accion: 'info',
  hayRespuesta: final.length > 0,
  // telemetria: sin esto no se puede saber si la rama info se sostiene sola o
  // vive del respaldo (que seria sintoma de que el agente nunca usa su tool).
  infoDelAgente: texto.length > 0,
  infoDelRespaldo: !texto && respaldo.length > 0,
  notas: 'v10-info' + (texto ? ' fuente=agente' : (respaldo ? ' fuente=tabla' : ' fuente=ninguna'))
    + ' filas=' + filas.length + ' relevantes=' + relevantes.length
    + (temas.length ? ' temas=' + temas.join(',') : ''),
} }];
